  void CaptureKeys(Control root){foreach(Control c in root.Controls){string key=L.Key(c.Text);if(key!=null)textKeys[c]=key;string hint=L.Key(hints.GetToolTip(c));if(hint!=null)hintKeys[c]=hint;var g=c as DataGridView;if(g!=null)foreach(DataGridViewColumn col in g.Columns){key=L.Key(col.HeaderText);if(key!=null)headerKeys[col]=key;}CaptureKeys(c);}}
  void ChangeLanguage(int index){if(changingLanguage||busy||index<0)return;changingLanguage=true;string prior=L.Language;L.Language=L.Languages[index];try{SaveSettings();}catch(Exception ex){L.Language=prior;languageChoice.SelectedIndex=settingsLanguage.SelectedIndex=Array.IndexOf(L.Languages,prior);changingLanguage=false;Error(ex);return;}
   languageChoice.SelectedIndex=settingsLanguage.SelectedIndex=index;SuspendLayout();foreach(var p in textKeys)p.Key.Text=L.Get(p.Value);foreach(var p in hintKeys)hints.SetToolTip(p.Key,L.Get(p.Value));foreach(var p in headerKeys)p.Key.HeaderText=L.Get(p.Value);
