  void SetExperienceBusy(bool value){languageChoice.Enabled=settingsLanguage.Enabled=search.Enabled=filter.Enabled=sort.Enabled=!value;}
  void ApplyFilter(){if(grid.Rows.Count!=rows.Count||populating)return;grid.CurrentCell=null;int visible=0;for(int i=0;i<rows.Count;i++){var r=rows[i];string name=r.Package==null?r.Installed.name:r.Package.Manifest.name;bool update=r.Installed!=null&&r.Package!=null&&new Version(r.Installed.version)<new Version(r.Package.Manifest.version);bool show=name.IndexOf(search.Text.Trim(),StringComparison.CurrentCultureIgnoreCase)>=0&&(filter.SelectedIndex<=0||filter.SelectedIndex==1&&r.Installed!=null||filter.SelectedIndex==2&&r.Installed==null||filter.SelectedIndex==3&&update);grid.Rows[i].Visible=show;if(!show)grid.Rows[i].Cells[0].Value=false;else visible++;}
