  void UpdateSelection(){if(selectionCount==null)return;int selected=grid.Rows.Cast<DataGridViewRow>().Count(r=>r.Visible&&Convert.ToBoolean(r.Cells[0].Value));int visible=grid.Rows.Cast<DataGridViewRow>().Count(r=>r.Visible);selectionCount.Text=string.Format(L.Get("SelectionCount"),selected,visible,rows.Count);if(installButton!=null&&grid.Rows.Count==rows.Count){var checkedRows=grid.Rows.Cast<DataGridViewRow>().Where(r=>r.Visible&&Convert.ToBoolean(r.Cells[0].Value)).Select(r=>rows[r.Index]).ToList();bool targetValid=InstallTarget.IsRoot(game.Text.Trim(),serverMode);installButton.Enabled=!busy&&targetValid&&checkedRows.Count>0&&checkedRows.All(r=>r.Package!=null&&string.IsNullOrEmpty(r.ServerIssue)&&string.IsNullOrEmpty(r.Conflict));uninstallButton.Enabled=!busy&&targetValid&&checkedRows.Count>0&&checkedRows.All(r=>r.Installed!=null);}}
  void CheckVisible(bool value){if(busy)return;foreach(DataGridViewRow r in grid.Rows)if(r.Visible&&!r.Cells[0].ReadOnly)r.Cells[0].Value=value;UpdateSelection();}
  void SortRows(){if(populating||changingLanguage||rows.Count==0)return;var chosen=new HashSet<Row>(Selected());Func<Row,string> name=r=>r.Package==null?r.Installed.name:r.Package.Manifest.name;rows=sort.SelectedIndex==1?rows.OrderByDescending(name,StringComparer.CurrentCultureIgnoreCase).ToList():sort.SelectedIndex==2?rows.OrderByDescending(r=>r.Installed!=null).ThenBy(name,StringComparer.CurrentCultureIgnoreCase).ToList():rows.OrderBy(name,StringComparer.CurrentCultureIgnoreCase).ToList();populating=true;grid.Rows.Clear();foreach(var row in rows){int index=grid.Rows.Add(chosen.Contains(row),name(row),null,"","");var cell=(DataGridViewComboBoxCell)grid.Rows[index].Cells[2];if(row.Package!=null){cell.DisplayMember="Label";cell.ValueMember="Key";cell.DataSource=row.Options;cell.Value=row.Package.Folder;}else{cell.Items.Add("—");cell.Value="—";cell.ReadOnly=true;}RefreshRow(index);}populating=false;ApplyFilter();}
  bool ConfirmInstall(List<Row> chosen){return Dialogs.Show(this,L.Get("ReviewInstall")+Environment.NewLine+game.Text+Environment.NewLine+Environment.NewLine+string.Join(Environment.NewLine,chosen.Select(r=>r.Package.Manifest.name+" · "+(r.Installed==null?"—":r.Installed.version)+" → "+r.Package.Manifest.version))+Environment.NewLine+Environment.NewLine+L.Get("CloseGame"),L.Get("Text118"),MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;}
  void DetectConflicts(List<InstalledPackage> installed){
   var owners=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(var p in installed)foreach(var f in p.files)owners[f.target]=p.id;
   foreach(var row in rows){row.Conflict=null;if(row.Package==null)continue;var matches=row.Package.Manifest.files.Where(f=>owners.ContainsKey(f.target)&&owners[f.target]!=row.Package.Manifest.id).Select(f=>f.target).ToArray();if(matches.Length>0)row.Conflict=L.Get("ConflictHelp")+Environment.NewLine+string.Join(Environment.NewLine,matches.Take(8));}
   for(int i=0;i<rows.Count;i++)RefreshRow(i);
  }
  string RowError(Row row){string error;return rowErrors.TryGetValue(row.Package==null?row.Installed.id:row.Package.Manifest.id,out error)?error:null;}
  void RecordRowError(Row row,Exception ex){if(InvokeRequired){Invoke(new Action<Row,Exception>(RecordRowError),row,ex);return;}rowErrors[row.Package==null?row.Installed.id:row.Package.Manifest.id]=Problems.Explain(ex);}
  void SetRowOperation(Row row,string operation){if(InvokeRequired){Invoke(new Action<Row,string>(SetRowOperation),row,operation);return;}row.Operation=operation;int i=rows.IndexOf(row);if(i>=0)RefreshRow(i);}
  void CopyText(string text){try{Clipboard.SetText(text);}catch(Exception ex){Dialogs.Show(this,L.Get("CopyFailed")+Environment.NewLine+ex.Message,Text);}}
  bool fittingGrid;
  void FitGrid(DataGridView view,float[] weights){if(fittingGrid||view.Columns.Count!=weights.Length||view.Width<100)return;fittingGrid=true;try{view.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.None;float total=weights.Sum();int width=Math.Max(100,view.ClientSize.Width-SystemInformation.VerticalScrollBarWidth-4);for(int i=0;i<weights.Length;i++){view.Columns[i].MinimumWidth=20;view.Columns[i].FillWeight=weights[i];view.Columns[i].Width=Math.Max(20,(int)(width*weights[i]/total));}view.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;}finally{fittingGrid=false;}}
  static void DrawCombo(object sender,DrawItemEventArgs e){var box=(ComboBox)sender;bool selected=(e.State&DrawItemState.Selected)!=0;using(var brush=new SolidBrush(selected?Color.FromArgb(44,81,113):Color.FromArgb(32,43,58)))e.Graphics.FillRectangle(brush,e.Bounds);string text=e.Index<0?box.Text:Convert.ToString(box.Items[e.Index]);TextRenderer.DrawText(e.Graphics,text,e.Font,e.Bounds,box.Enabled?Color.FromArgb(231,238,249):Color.Gray,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);e.DrawFocusRectangle();}
  static void Theme(Control root){root.BackColor=Color.FromArgb(23,30,42);root.ForeColor=Color.FromArgb(225,232,242);foreach(Control c in root.Controls){Theme(c);var button=c as System.Windows.Forms.Button;if(button!=null){button.BackColor=Color.FromArgb(39,53,72);button.ForeColor=Color.White;button.FlatStyle=FlatStyle.Flat;button.FlatAppearance.BorderColor=Color.FromArgb(66,84,108);button.FlatAppearance.MouseOverBackColor=Color.FromArgb(53,76,103);button.MinimumSize=new Size(0,36);if(button.Text==L.Get("Text009"))button.BackColor=Color.FromArgb(26,110,170);if(button.Text==L.Get("Text011")||button.Text==L.Get("Text040"))button.ForeColor=Color.FromArgb(255,174,160);}
    var combo=c as ComboBox;if(combo!=null){combo.DrawMode=DrawMode.OwnerDrawFixed;combo.ItemHeight=22;combo.DrawItem+=DrawCombo;combo.FlatStyle=FlatStyle.Flat;}
    if(c is TextBox||c is ComboBox){c.BackColor=Color.FromArgb(32,43,58);c.ForeColor=Color.FromArgb(231,238,249);}var g=c as DataGridView;if(g!=null){g.BackgroundColor=Color.FromArgb(23,30,42);g.EnableHeadersVisualStyles=false;g.GridColor=Color.FromArgb(50,63,80);g.DefaultCellStyle.BackColor=Color.FromArgb(29,39,53);g.DefaultCellStyle.ForeColor=Color.FromArgb(231,238,249);g.DefaultCellStyle.SelectionBackColor=Color.FromArgb(44,81,113);g.DefaultCellStyle.SelectionForeColor=Color.White;g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(33,44,59);g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(39,53,72);g.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;g.BorderStyle=BorderStyle.None;g.DefaultCellStyle.Padding=new Padding(4);}}
